}

.nav-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: var(--spacing-md);
}

.nav-links a {
    font-weight: 500;
    font-size: 0.95rem;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--secondary);
}

.nav-icons {
    display: flex;
    gap: var(--spacing-sm);
}

.icon-btn {
    font-size: 1.2rem;
    padding: var(--spacing-xs);
    position: relative;
}

#cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--primary);
    color: var(--white);
    font-size: 0.6rem;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    background: var(--accent);
    padding: var(--spacing-lg) 0;
}

.hero-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: var(--spacing-lg);
}

.badge {
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 1px;
    font-weight: 600;
    color: var(--secondary);
    display: block;
    margin-bottom: var(--spacing-sm);
}

.hero-text h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: var(--spacing-md);
    font-weight: 700;
}

.hero-text p {
    font-size: 1.1rem;
    color: var(--secondary);
    margin-bottom: var(--spacing-md);
    max-width: 450px;
}

.btn {
    display: inline-block;
    padding: 1rem 2rem;
    font-weight: 600;
    transition: var(--transition);
}

.btn-primary {
    background: var(--primary);
    color: var(--white);
}

.btn-primary:hover {
    opacity: 0.9;
    transform: translateY(-2px);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-md);
}

