.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.add-to-cart {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    background: var(--primary);
    color: var(--white);
    padding: 0.8rem;
    transform: translateY(100%);
    transition: var(--transition);
}

.product-card:hover .add-to-cart {
    transform: translateY(0);
}

.product-info h3 {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.product-price {
    font-weight: 600;
}

.old-price {
    text-decoration: line-through;
    color: var(--secondary);
    font-size: 0.9rem;
    margin-right: 0.5rem;
}

/* Deals */
.deals-section {
    background: #fafafa;
}

.deals-banner {
    background: var(--white);
    padding: var(--spacing-lg);
    border: 1px solid var(--border);
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-sm);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-md);
    margin-top: var(--spacing-md);
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: var(--spacing-md);
}

.editorial-card {
    position: relative;
    overflow: hidden;
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial-info {
    position: absolute;
    bottom: 0;
    left: 0;
    padding: var(--spacing-md);
    color: var(--white);
    background: linear-gradient(transparent, rgba(0,0,0,0.7));
    width: 100%;
}

