    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.editorial-sub-grid .editorial-card {
    height: calc(250px - var(--spacing-sm));
}

.btn-text {
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
    margin-top: 1rem;
    display: inline-block;
}

/* Footer */
.footer {
    background: #f9f9f9;
    padding: var(--spacing-lg) 0 var(--spacing-md);
    border-top: 1px solid var(--border);
    margin-top: var(--spacing-lg);
}

.footer-content {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-brand .logo {
    margin-bottom: var(--spacing-sm);
    display: block;
}

.footer-brand p {
    color: var(--secondary);
    max-width: 250px;
}

.footer-links h4, .footer-newsletter h4 {
    margin-bottom: var(--spacing-sm);
    font-size: 1rem;
}

.footer-links ul li {
    margin-bottom: 0.5rem;
}

.footer-links a {
    color: var(--secondary);
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--primary);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border: 1px solid var(--border);
}

.newsletter-form button {
    background: var(--primary);
    color: var(--white);
    padding: 0.8rem 1.5rem;
}

.footer-bottom {
    border-top: 1px solid var(--border);
