+    gap: var(--spacing-md);
+    margin-top: var(--spacing-md);
+}
+
+/* Editorial */
+.editorial-grid {
+    display: grid;
+    grid-template-columns: 2fr 1fr;
+    gap: var(--spacing-md);
+}
+
+.editorial-card {
+    position: relative;
+    overflow: hidden;
+}
+
+.editorial-card img {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+}
+
+.editorial-info {
+    position: absolute;
+    bottom: 0;
+    left: 0;
+    padding: var(--spacing-md);
+    color: var(--white);
+    background: linear-gradient(transparent, rgba(0,0,0,0.7));
+    width: 100%;
+}
+
+.editorial-card.large {
+    height: 500px;
+}
+
+.editorial-sub-grid {
+    display: flex;
+    flex-direction: column;
+    gap: var(--spacing-md);
+}
+
+.editorial-sub-grid .editorial-card {
+    height: calc(250px - var(--spacing-sm));
+}
+
+.btn-text {
+    font-weight: 600;
+    text-transform: uppercase;
+    font-size: 0.8rem;
+    letter-spacing: 1px;
+    margin-top: 1rem;
+    display: inline-block;
+}
+
+/* Footer */
+.footer {
+    background: #f9f9f9;
+    padding: var(--spacing-lg) 0 var(--spacing-md);
+    border-top: 1px solid var(--border);
+    margin-top: var(--spacing-lg);
+}
+
+.footer-content {
+    display: grid;
+    grid-template-columns: 2fr 1fr 1fr 2fr;
+    gap: var(--spacing-lg);
+    margin-bottom: var(--spacing-lg);
+}
+
+.footer-brand .logo {
+    margin-bottom: var(--spacing-sm);
+    display: block;
+}
+
+.footer-brand p {
+    color: var(--secondary);
+    max-width: 250px;
+}
+
+.footer-links h4, .footer-newsletter h4 {
+    margin-bottom: var(--spacing-sm);
+    font-size: 1rem;
+}
+
+.footer-links ul li {
+    margin-bottom: 0.5rem;
+}
+
+.footer-links a {
+    color: var(--secondary);
+    transition: var(--transition);
+}
+
+.footer-links a:hover {
+    color: var(--primary);
+}
+
+.newsletter-form {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.newsletter-form input {
+    flex: 1;
+    padding: 0.8rem;
+    border: 1px solid var(--border);
+}
+
+.newsletter-form button {
+    background: var(--primary);
+    color: var(--white);
+    padding: 0.8rem 1.5rem;
+}
+
+.footer-bottom {
+    border-top: 1px solid var(--border);
+    padding-top: var(--spacing-md);
+    text-align: center;
+    color: var(--secondary);
+    font-size: 0.85rem;
+}
+
+/* Responsive */
+@media (max-width: 992px) {
+    .hero-content {
+        grid-template-columns: 1fr;
+        text-align: center;
+    }
+    .hero-text p {
+        margin: 0 auto var(--spacing-md);
+    }
+    .footer-content {
+        grid-template-columns: 1fr 1fr;
+    }
+    .editorial-grid {
+        grid-template-columns: 1fr;
+    }
+}
+
+@media (max-width: 600px) {
+    .nav-links {
+        display: none;
+    }
+    .hero-text h1 {
+        font-size: 2.5rem;
+    }
+    .footer-content {
+        grid-template-columns: 1fr;
+    }
+}
+
