    {
        id: 1,
        name: "Minimalist Ceramic Vase",
        price: 45.00,
        image: "https://images.unsplash.com/photo-1581783898377-1c85bf937427?auto=format&fit=crop&q=80&w=400",
        category: "Home"
    },
    {
        id: 2,
        name: "Linen Lounge Set",
        price: 120.00,
        image: "https://images.unsplash.com/photo-1594932224011-042041c854fa?auto=format&fit=crop&q=80&w=400",
        category: "Apparel"
    },
    {
        id: 3,
        name: "Walnut Desk Organizer",
        price: 85.00,
        image: "https://images.unsplash.com/photo-1591129841117-3adfd313e34f?auto=format&fit=crop&q=80&w=400",
        category: "Office"
    },
    {
        id: 4,
        name: "Leather Weekend Bag",
        price: 210.00,
        image: "https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&q=80&w=400",
        category: "Accessories"
    }
];

const DEALS = [
    {
        id: 101,
        name: "Organic Cotton Tee",
        price: 28.00,
        oldPrice: 40.00,
        image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&q=80&w=400"
    },
    {
        id: 102,
        name: "Recycled Glass Tumbler",
        price: 12.00,
        oldPrice: 18.00,
        image: "https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&q=80&w=400"
    }
];

let cartCount = 0;

function renderProducts() {
    const grid = document.getElementById('featured-grid');
    if (!grid) return;

    grid.innerHTML = PRODUCTS.map(product => `
        <div class="product-card">
            <div class="product-image">
                <img src="${product.image}" alt="${product.name}" loading="lazy">
                <button class="add-to-cart" onclick="addToCart(event)">Add to Cart</button>
            </div>
            <div class="product-info">
                <span class="badge" style="margin-bottom: 5px">${product.category}</span>
                <h3>${product.name}</h3>
                <p class="product-price">$${product.price.toFixed(2)}</p>
            </div>
        </div>
    `).join('');
}

function renderDeals() {
    const grid = document.getElementById('deals-grid');
    if (!grid) return;

    grid.innerHTML = DEALS.map(deal => `
        <div class="product-card">
            <div class="product-image">
                <img src="${deal.image}" alt="${deal.name}" loading="lazy">
                <button class="add-to-cart" onclick="addToCart(event)">Add to Cart</button>
            </div>
            <div class="product-info">
                <h3>${deal.name}</h3>
                <p class="product-price">
                    <span class="old-price">$${deal.oldPrice.toFixed(2)}</span>
                    $${deal.price.toFixed(2)}
                </p>
            </div>
        </div>
    `).join('');
}

function addToCart(event) {
    if (event) {
        const btn = event.target;
        const originalText = btn.textContent;
        btn.textContent = 'Added!';
        btn.style.background = '#4CAF50';

        setTimeout(() => {
            btn.textContent = originalText;
            btn.style.background = '';
        }, 1000);
    }

    cartCount++;
    document.getElementById('cart-count').textContent = cartCount;
}

// Newsletter submission
document.querySelector('.newsletter-form')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = e.target.querySelector('input').value;
    if (email) {
        alert(`Thanks for joining, ${email}!`);
        e.target.reset();
    }
});

// Smooth scroll for nav links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        e.preventDefault();
        document.querySelector(this.getAttribute('href')).scrollIntoView({
            behavior: 'smooth'
        });
    });
});

// Initialize
document.addEventListener('DOMContentLoaded', () => {
    renderProducts();
    renderDeals();
});
